def tree(folder, indent=0):
    lines = []
    items = sorted(Path(folder).iterdir(), key=lambda p: (not p.is_dir(), p.name))
    for p in items:
        if p.is_dir():
            lines.append(" " * indent + p.name + "/")
            lines.extend(tree(p, indent + 2))
        else:
            lines.append(" " * indent + p.name)
    return lines

